auto heapify = [](auto& self, int arr[], int n, int i) -> void {
    int largest = i;
    int left = 2 * i + 1;
    int right = 2 * i + 2;

    if (left < n && arr[left] > arr[largest]) {
        largest = left;
    }

    if (right < n && arr[right] > arr[largest]) {
        largest = right;
    }

    if (largest != i) {
        int temp = arr[i];
        arr[i] = arr[largest];
        arr[largest] = temp;
        self(self, arr, n, largest);
    }
};

for (int i = size / 2 - 1; i >= 0; i--) {
    heapify(heapify, arr, size, i);
}

for (int i = size - 1; i > 0; i--) {
    int temp = arr[0];
    arr[0] = arr[i];
    arr[i] = temp;
    heapify(heapify, arr, i, 0);
}
